                let t0 := add(s0, 0x1797130f4b7a3e1777eb757bc6f287f6ab0fb85f6be63b09f3b16ef2b1405d38)
                let p0 := mulmod(t0, t0, F)
                s0 := mulmod(mulmod(p0, p0, F), t0, F)
                let t1 := add(s1, 0x0a76225dc04170ae3306c85abab59e608c7f497c20156d4d36c668555decc6e5)
                let p1 := mulmod(t1, t1, F)
                s1 := mulmod(mulmod(p1, p1, F), t1, F)
                let t2 := add(s2, 0x1fffb9ec1992d66ba1e77a7b93209af6f8fa76d48acb664796174b5326a31a5c)
                let p2 := mulmod(t2, t2, F)
                s2 := mulmod(mulmod(p2, p2, F), t2, F)
                let t3 := add(s3, 0x25721c4fc15a3f2853b57c338fa538d85f8fbba6c6b9c6090611889b797b9c5f)
                let p3 := mulmod(t3, t3, F)
                s3 := mulmod(mulmod(p3, p3, F), t3, F)
            }
            {
                let t0 := add(s0, s1)
                let t1 := add(s2, s3)
                let t2 := add(add(s1, s1), t1)
                let t3 := add(add(s3, s3), t0)
                let b2 := addmod(t1, t1, F)
                let b4 := add(b2, b2)
                let a2 := addmod(t0, t0, F)
                let a4 := add(a2, a2)
                t2 := mod(t2, F)
                t3 := mod(t3, F)
                let e := add(b4, t3)
                let f := add(a4, t2)
                s0 := add(t3, f)
                s1 := f
                s2 := add(t2, e)
                s3 := e
            }
            {
                let t0 := add(s0, 0x0c817fd42d5f7a41215e3d07ba197216adb4c3790705da95eb63b982bfcaf75a)
                let p0 := mulmod(t0, t0, F)
                s0 := mulmod(mulmod(p0, p0, F), t0, F)
                let t1 := add(s1, 0x13abe3f5239915d39f7e13c2c24970b6df8cf86ce00a22002bc15866e52b5a96)
                let p1 := mulmod(t1, t1, F)
                s1 := mulmod(mulmod(p1, p1, F), t1, F)
                let t2 := add(s2, 0x2106feea546224ea12ef7f39987a46c85c1bc3dc29bdbd7a92cd60acb4d391ce)
                let p2 := mulmod(t2, t2, F)
                s2 := mulmod(mulmod(p2, p2, F), t2, F)
                let t3 := add(s3, 0x21ca859468a746b6aaa79474a37dab49f1ca5a28c748bc7157e1b3345bb0f959)
                let p3 := mulmod(t3, t3, F)
                s3 := mulmod(mulmod(p3, p3, F), t3, F)
            }
            {
                let t0 := add(s0, s1)
                let t1 := add(s2, s3)
                let t2 := add(add(s1, s1), t1)
                let t3 := add(add(s3, s3), t0)
                let b2 := addmod(t1, t1, F)
                let b4 := add(b2, b2)
                let a2 := addmod(t0, t0, F)
                let a4 := add(a2, a2)
                t2 := mod(t2, F)
                t3 := mod(t3, F)
                let e := add(b4, t3)
                let f := add(a4, t2)
                s0 := add(t3, f)
                s1 := f
                s2 := add(t2, e)
                s3 := e
            }
            {
                let t0 := add(s0, 0x05ccd6255c1e6f0c5cf1f0df934194c62911d14d0321662a8f1a48999e34185b)
                let p0 := mulmod(t0, t0, F)
                s0 := mulmod(mulmod(p0, p0, F), t0, F)
                let t1 := add(s1, 0x0f0e34a64b70a626e464d846674c4c8816c4fb267fe44fe6ea28678cb09490a4)
                let p1 := mulmod(t1, t1, F)
                s1 := mulmod(mulmod(p1, p1, F), t1, F)
                let t2 := add(s2, 0x0558531a4e25470c6157794ca36d0e9647dbfcfe350d64838f5b1a8a2de0d4bf)
                let p2 := mulmod(t2, t2, F)
                s2 := mulmod(mulmod(p2, p2, F), t2, F)
                let t3 := add(s3, 0x09d3dca9173ed2faceea125157683d18924cadad3f655a60b72f5864961f1455)
                let p3 := mulmod(t3, t3, F)
                s3 := mulmod(mulmod(p3, p3, F), t3, F)
            }
            {
                let t0 := add(s0, s1)
                let t1 := add(s2, s3)
                let t2 := add(add(s1, s1), t1)
                let t3 := add(add(s3, s3), t0)
                let b2 := addmod(t1, t1, F)
                let b4 := add(b2, b2)
                let a2 := addmod(t0, t0, F)
                let a4 := add(a2, a2)
                t2 := mod(t2, F)
                t3 := mod(t3, F)
                let e := add(b4, t3)
                let f := add(a4, t2)
                s0 := add(t3, f)
                s1 := f
                s2 := add(t2, e)
                s3 := e
            }
            {
                let t0 := add(s0, 0x0328cbd54e8c0913493f866ed03d218bf23f92d68aaec48617d4c722e5bd4335)
                let p0 := mulmod(t0, t0, F)
                s0 := mulmod(mulmod(p0, p0, F), t0, F)
                let t1 := add(s1, 0x2bf07216e2aff0a223a487b1a7094e07e79e7bcc9798c648ee3347dd5329d34b)
                let p1 := mulmod(t1, t1, F)
                s1 := mulmod(mulmod(p1, p1, F), t1, F)
                let t2 := add(s2, 0x1daf345a58006b736499c583cb76c316d6f78ed6a6dffc82111e11a63fe412df)
                let p2 := mulmod(t2, t2, F)
                s2 := mulmod(mulmod(p2, p2, F), t2, F)
                let t3 := add(s3, 0x176563472456aaa746b694c60e1823611ef39039b2edc7ff391e6f2293d2c404)
                let p3 := mulmod(t3, t3, F)
                s3 := mulmod(mulmod(p3, p3, F), t3, F)
            }
            {
                let t0 := add(s0, s1)
                let t1 := add(s2, s3)
                let t2 := add(add(s1, s1), t1)
                let t3 := add(add(s3, s3), t0)
                let b2 := addmod(t1, t1, F)
                let b4 := add(b2, b2)
                let a2 := addmod(t0, t0, F)
                let a4 := add(a2, a2)
                t2 := mod(t2, F)
                t3 := mod(t3, F)
                let e := add(b4, t3)
                let f := add(a4, t2)
                s0 := add(t3, f)
                s1 := f
                s2 := add(t2, e)
                s3 := e
            }

            s0 := mod(s0, F)
            s1 := mod(s1, F)
            s2 := mod(s2, F)
            s3 := mod(s3, F)

            r0 := s0
            r1 := s1
            r2 := s2
            r3 := s3
        }
    }

    /// @notice Hash one field element
    function hash1(uint a) public pure returns (uint) {
        (uint r,,,) = _permute(a, 0, 0, 18446744073709551616);
        return r;
    }

    /// @notice Hash two field elements (Merkle tree default)
    function hash2(uint a, uint b) public pure returns (uint) {
        (uint r,,,) = _permute(a, b, 0, 36893488147419103232);
        return r;
    }

    /// @notice Hash three field elements
    function hash3(uint a, uint b, uint c) public pure returns (uint) {
        (uint r,,,) = _permute(a, b, c, 55340232221128654848);
        return r;
    }

    /// @notice Sponge hash for variable-length input (rate=3, Poseidon2 T4)
    function hashMany(uint[] memory inputs) public pure returns (uint) {
        uint s0 = 0;
        uint s1 = 0;
        uint s2 = 0;
        uint s3 = inputs.length << 64; // domain separator in capacity
        uint bufferSize = 0;
        for (uint i = 0; i < inputs.length; i++) {
            if (bufferSize == 3) {
                (s0, s1, s2, s3) = _permute(s0, s1, s2, s3);
                bufferSize = 0;
            }
            if (bufferSize == 0) {
                s0 = addmod(s0, inputs[i], FIELD_MODULUS);
            } else if (bufferSize == 1) {
                s1 = addmod(s1, inputs[i], FIELD_MODULUS);
            } else {
                s2 = addmod(s2, inputs[i], FIELD_MODULUS);
            }
            bufferSize++;
        }
        (s0,,,) = _permute(s0, s1, s2, s3);
        return s0;
    }
}
"
